-- GENERATED by `wfj generate` from data/gossip/gossip-88.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["8803591ac52acfac"] = { "Nel corso dei millenni, Ilyenia Moonfire ha padroneggiato numerose armi e ora si offre di addestrare altri al loro uso. Se desideri addestrarti, la trovi alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧.", "." },
  ["8807e3472e9cbbbf"] = { "Il sangue di mille soldati dell'⟦Alliance=Alleanza⟧ verserò... Nessuno potrà resistere alla potenza del Signore del Ghiaccio!", "." },
  ["8819a603dca34569"] = { "Là! Laggiù!", "." },
  ["882d57c56c75f582"] = { "Quando le energie allineate positivamente si scontrano con quelle a carica negativa, non si annullano a vicenda.", "." },
  ["8835346a6316d9ce"] = { "Portami con te, <signore/signora>.", "." },
  ["883ac3a716604c7e"] = { "Il corpo è quello di una guerriera orchessa.\n\nÈ evidente che è morta in battaglia, probabilmente contro i verrospini della zona.", "." },
  ["883c3b77b05836b6"] = { "Dov'è l'anziano Starglade?", "." },
  ["88460fd80a9dfb5d"] = { "Sul lato est di ⟦Razor Hill=Tranciacolle⟧, dietro la caserma, troverai Dhugru Gorelust.", "." },
  ["884f59941665e810"] = { "La ⟦Cathedral of Light=Cattedrale della Luce⟧, in Cathedral Square, ospita i sacerdoti di ⟦Stormwind=Roccavento⟧. Lì troverai la somma sacerdotessa Laurena.", "." },
  ["8854d4ffcb4004c2"] = { "Niente paura, Bodley è al lavoro! Vediamo un po', ah sì... eccolo. Lascia solo che lo evochi... e, voilà!\n\nCerca di non perderlo di nuovo, {name}.", "." },
  ["885a0b3f04191312"] = { "La terra della luce stellare eterna, Kalimdor, era una madre premurosa per tutte le sue creature. La magia del ⟦Well of Eternity=Pozzo dell'Eternità⟧ permeava la terra e potenziava la moltitudine di flora e fauna che avrebbe fatto del mondo la sua casa. Da questo etere magico nacquero i silitidi. Fu attraverso i silitidi che il cupo Dio Antico avrebbe cercato di raggiungere e spezzare il mondo che un tempo stringeva nella sua morsa spietata.", "." },
  ["88748bdff3f868bf"] = { "Ehi, Pratt, puoi insegnarmi di nuovo a fare gli ⟦Wild Leather Shoulders=Spallacci di Cuoio Selvatico⟧?", "." },
  ["8877958c70865bce"] = { "La Luce deve prevalere!", "." },
  ["8879c34c31f71c53"] = { "Cercate rifugio a ⟦Hearthglen=Valsalda⟧! È la nostra unica speranza!", "." },
  ["887a959828773516"] = { "Sono Augustus, e i miei prezzi sono FOLLI!", "." },
  ["887e9c3192c2a238"] = { "Sembra pericoloso.", "." },
  ["8880013c1f11bf95"] = { "Anch'io cerco un tale potere.", "." },
  ["8896af72f7bd083f"] = { "Vediamo se ti piace un assaggio di questo!", "." },
  ["8899559688ec9e5d"] = { "Abbiamo abbastanza rifornimenti per lanciare un assalto di terra. Se vuoi dare l'ordine, e pensi di averne i requisiti, parla con il sergente Yazra Bloodsnarl.", "." },
  ["889d2ecba8e95683"] = { "Cosa?? Le ⟦Burning Blade=Lame Ardenti⟧ si stanno diffondendo! Dobbiamo indagare!", "." },
  ["88a077bedd8cc69f"] = { "Non vedi che ho da fare? Spero sia una cosa importante.", "." },
  ["88a09c7d6c3c385b"] = { "La ⟦Irondeep Mine=Miniera di Ferrofondo⟧ si trova in territorio dell'⟦Alliance=Alleanza⟧, a nord del ⟦Stormpike Graveyard=Cimitero dei Piccatonante⟧.\n\nÈ controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["88a50a42dfa45e02"] = { "<Benvenuto/Benvenuta> al Blue Moon Odds and Ends, {class}. Se hai domande, fammelo sapere.", "." },
  ["88ab338c3e4424f2"] = { "Uccidete {name}!", "." },
  ["88ada396c3268b70"] = { "Ih! {name} viene dritto verso di noi!", "." },
  ["88adff1ebf6b56cf"] = { "Le mie viverne sono addestrate a volare veloci nell'aria calda delle ⟦Barrens=Savane⟧.", "." },
  ["88afd52c86805c48"] = { "Kodo, <amico/amica> <mio/mia>! Addestrati fin da giovani e cresciuti nella Piana Dorata di Mulgore, questi splendidi animali diventeranno destrieri ancora più splendidi! Prego, dai un'occhiata alla mia selezione, e vedi da te perché noi tauren abbiamo imparato a fare affidamento su queste magnifiche creature!", "." },
  ["88d4aed9e81555e1"] = { "Ehi, {name}.\n\nLotwil non è il capo più perspicace che abbia avuto. Si fa davvero prendere dal suo lavoro. Così tanto che a volte i suoi servitori non mangiano, o non vengono pagati.\n\n<Lucien guarda Lotwil accigliato.>\n\nMa questo non vuol dire che debba soffrire tu.", "." },
  ["88e0c485f95125db"] = { "Parlami della ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["88e6ea0c1bd6d4df"] = { "Cerchi questo: [⟦Red Scepter Shard=Frammento di Scettro Rosso⟧]? Vieni a prenderlo...", "." },
  ["88e99a84064c4fe4"] = { "<Benvenuto/Benvenuta> nella mia forgia, fabbro. Lascia che ti sveli un piccolo segreto. Di nessuno, nessuno al mondo puoi fidarti. Non degli uomini, non delle donne, non delle bestie... di questo puoi fidarti: dell'acciaio.", "." },
  ["88f0299019d303e0"] = { "Ecco fatto, entrambe le parti hanno raccolto tutto. Ora tutto viene trasportato a ⟦Silithus=Silitus⟧ e dovrebbe arrivare in meno di un giorno. Quando sarà fatto e qualcuno suonerà il gong sull'Altare dello Scarabeo con lo Scettro delle Sabbie Mutevoli, la guerra avrà inizio!", "." },
  ["88f6671794611742"] = { "{name}! Aiuto!", "." },
  ["88fd3722fdc0a9b5"] = { "Grazie, <vecchio/vecchia> <amico/amica>. Hai fatto la cosa giusta.", "." },
})
